<?php
declare(strict_types=1);
namespace App\Controllers\Api;
use CodeIgniter\HTTP\ResponseInterface;

class LabourWagesController extends LabourApiController
{
 public function index():ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$b=db_connect()->table('labour_wage_periods wp')->select('wp.*,p.project_code,p.project_name,s.site_name,c.contractor_name,st.status_code,st.status_name')->join('projects p','p.id=wp.project_id')->join('project_sites s','s.id=wp.site_id')->join('labour_contractors c','c.id=wp.contractor_id','left')->join('labour_wage_periods_status_masters st','st.id=wp.status_id')->where('wp.company_id',$this->companyId($u));foreach(['project_id','site_id','contractor_id','status_id']as$f)if(ctype_digit((string)($this->request->getGet($f)??'')))$b->where('wp.'.$f,(int)$this->request->getGet($f));return$this->ok('Wage periods retrieved successfully.','wage_periods',$b->orderBy('wp.id','DESC')->get()->getResultArray());}
 public function show(int$id):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$r=$this->record('labour_wage_periods',$id,$this->companyId($u));if(!$r)return$this->notFound();$r['lines']=db_connect()->table('labour_wage_lines l')->select('l.*,w.worker_code,w.worker_name,ps.payment_status_code,ps.payment_status_name')->join('labour_workers w','w.id=l.worker_id')->join('labour_wage_lines_payment_status_masters ps','ps.id=l.payment_status_id')->where('l.wage_period_id',$id)->get()->getResultArray();return$this->ok('Wage period retrieved successfully.','wage_period',$r);}
 public function create():ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$in=$this->input();if(!$in)return$this->invalid(['body'=>'A valid JSON request body is required.']);$e=$this->required($in,['project_id','site_id','period_code','period_start','period_end']);if(!$this->site((int)($in['site_id']??0),(int)($in['project_id']??0),$u,true))$e['site_id']='Select an accessible site belonging to the project.';if(($in['period_end']??'')<($in['period_start']??''))$e['period_end']='Period end cannot precede period start.';$c=$this->companyId($u);if(!empty($in['contractor_id'])&&!$this->record('labour_contractors',(int)$in['contractor_id'],$c,true))$e['contractor_id']='Select a valid contractor.';if(db_connect()->table('labour_wage_periods')->where('company_id',$c)->where('period_code',$in['period_code']??'')->countAllResults())$e['period_code']='Period code already exists.';if($e)return$this->invalid($e);$draft=$this->masterId('labour_wage_periods_status_masters','status_code','DRAFT');$d=array_intersect_key($in,array_flip(['project_id','site_id','period_code','period_start','period_end','contractor_id','remarks']));$d+=['company_id'=>$c,'status_id'=>$draft,'created_by'=>(int)$u->id,'updated_by'=>(int)$u->id,'created_at'=>$this->now(),'updated_at'=>$this->now()];db_connect()->table('labour_wage_periods')->insert($d);$id=(int)db_connect()->insertID();return$this->ok('Wage period created successfully.','wage_period',$this->record('labour_wage_periods',$id,$c),201);}
 public function update(int$id):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$c=$this->companyId($u);$p=$this->record('labour_wage_periods',$id,$c);if(!$p)return$this->notFound();if($this->periodStatus((int)$p['status_id'])!=='DRAFT')return$this->response->setStatusCode(409)->setJSON(['success'=>false,'message'=>'Only Draft wage periods can be edited.']);$in=$this->input();if(!$in)return$this->invalid(['body'=>'A valid JSON request body is required.']);$m=array_merge($p,$in);$e=$this->required($m,['project_id','site_id','period_code','period_start','period_end']);if(!$this->site((int)$m['site_id'],(int)$m['project_id'],$u,true))$e['site_id']='Select an accessible site belonging to the project.';if($m['period_end']<$m['period_start'])$e['period_end']='Period end cannot precede period start.';if(!empty($m['contractor_id'])&&!$this->record('labour_contractors',(int)$m['contractor_id'],$c,true))$e['contractor_id']='Select a valid contractor.';$q=db_connect()->table('labour_wage_periods')->where('company_id',$c)->where('period_code',$m['period_code'])->where('id !=',$id);if($q->countAllResults())$e['period_code']='Period code already exists.';if($e)return$this->invalid($e);$d=array_intersect_key($in,array_flip(['project_id','site_id','period_code','period_start','period_end','contractor_id','remarks']));$d+=['updated_by'=>(int)$u->id,'updated_at'=>$this->now()];db_connect()->table('labour_wage_periods')->where(['id'=>$id,'company_id'=>$c])->update($d);return$this->ok('Wage period updated successfully.','wage_period',$this->record('labour_wage_periods',$id,$c));}
 public function calculate(int$id):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$c=$this->companyId($u);$p=$this->record('labour_wage_periods',$id,$c);if(!$p)return$this->notFound();if(!in_array($this->periodStatus((int)$p['status_id']),['DRAFT','CALCULATED'],true))return$this->response->setStatusCode(409)->setJSON(['success'=>false,'message'=>'Only Draft or Calculated wage periods can be calculated.']);$approved=$this->masterId('labour_attendance_batches_status_masters','status_code','APPROVED');$locked=$this->masterId('labour_attendance_batches_status_masters','status_code','LOCKED');$rows=db_connect()->table('labour_attendance_entries e')->select("e.worker_id,e.assignment_id,a.agreed_wage_rate,a.overtime_rate,a.wage_basis_id,SUM(CASE WHEN ast.attendance_status_code='PRESENT' THEN 1 WHEN ast.attendance_status_code='HALF_DAY' THEN 0.5 ELSE 0 END) payable_days,SUM(e.regular_hours) regular_hours,SUM(e.overtime_hours) overtime_hours",false)->join('labour_attendance_batches b','b.id=e.batch_id')->join('labour_project_assignments a','a.id=e.assignment_id')->join('labour_attendance_entries_attendance_status_masters ast','ast.id=e.attendance_status_id')->where('b.project_id',$p['project_id'])->where('b.site_id',$p['site_id'])->where('b.attendance_date >=',$p['period_start'])->where('b.attendance_date <=',$p['period_end'])->whereIn('b.status_id',array_values(array_filter([$approved,$locked])));if(!empty($p['contractor_id']))$rows->join('labour_workers w','w.id=e.worker_id')->where('w.contractor_id',$p['contractor_id']);$rows=$rows->groupBy(['e.worker_id','e.assignment_id','a.agreed_wage_rate','a.overtime_rate','a.wage_basis_id'])->get()->getResultArray();if(!$rows)return$this->invalid(['attendance'=>'No approved attendance exists for this wage period.']);$unpaid=$this->masterId('labour_wage_lines_payment_status_masters','payment_status_code','UNPAID');$db=db_connect();$db->transBegin();$db->table('labour_wage_lines')->where('wage_period_id',$id)->delete();foreach($rows as$r){$basis=db_connect()->table('labour_project_assignments_wage_basis_masters')->select('wage_basis_code')->where('id',$r['wage_basis_id'])->get()->getRowArray()['wage_basis_code']??'DAILY';$rate=(float)$r['agreed_wage_rate'];$regular=$basis==='HOURLY'?$rate*(float)$r['regular_hours']:$rate*(float)$r['payable_days'];$ot=(float)$r['overtime_rate']*(float)$r['overtime_hours'];$gross=$regular+$ot;$db->table('labour_wage_lines')->insert(['company_id'=>$c,'wage_period_id'=>$id,'worker_id'=>$r['worker_id'],'assignment_id'=>$r['assignment_id'],'payable_days'=>$r['payable_days'],'regular_hours'=>$r['regular_hours'],'overtime_hours'=>$r['overtime_hours'],'wage_rate'=>$rate,'regular_wage'=>$regular,'overtime_wage'=>$ot,'gross_amount'=>$gross,'net_amount'=>$gross,'payment_status_id'=>$unpaid,'created_by'=>(int)$u->id,'updated_by'=>(int)$u->id]);}$this->recalc($id);$sid=$this->masterId('labour_wage_periods_status_masters','status_code','CALCULATED');$db->table('labour_wage_periods')->where('id',$id)->update(['status_id'=>$sid,'updated_by'=>(int)$u->id]);$db->transCommit();return$this->show($id);}
 public function updateLine(int$p,int$l):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$period=$this->record('labour_wage_periods',$p,$this->companyId($u));$line=$this->record('labour_wage_lines',$l,$this->companyId($u));if(!$period||!$line||(int)$line['wage_period_id']!==$p)return$this->notFound();if($this->periodStatus((int)$period['status_id'])!=='CALCULATED')return$this->response->setStatusCode(409)->setJSON(['success'=>false,'message'=>'Wage lines can be adjusted only in Calculated status.']);$in=$this->input()??[];$d=array_intersect_key($in,array_flip(['allowance_amount','incentive_amount','advance_deduction','other_deduction','remarks']));$m=array_merge($line,$d);$m['gross_amount']=(float)$m['regular_wage']+(float)$m['overtime_wage']+(float)$m['allowance_amount']+(float)$m['incentive_amount'];$m['net_amount']=$m['gross_amount']-(float)$m['advance_deduction']-(float)$m['other_deduction'];$d['gross_amount']=$m['gross_amount'];$d['net_amount']=$m['net_amount'];$d['updated_by']=(int)$u->id;db_connect()->table('labour_wage_lines')->where('id',$l)->update($d);$this->recalc($p);return$this->ok('Wage line updated successfully.','wage_line',$this->record('labour_wage_lines',$l,$this->companyId($u)));}
 public function submit(int$id):ResponseInterface{return$this->periodTransition($id,'CALCULATED','SUBMITTED','SUBMIT');}public function approve(int$id):ResponseInterface{return$this->periodTransition($id,'SUBMITTED','APPROVED','APPROVE');}public function cancel(int$id):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$p=$this->record('labour_wage_periods',$id,$this->companyId($u));if(!$p)return$this->notFound();if(in_array($this->periodStatus((int)$p['status_id']),['PARTIALLY_PAID','PAID'],true))return$this->response->setStatusCode(409)->setJSON(['success'=>false,'message'=>'A paid wage period cannot be cancelled.']);return$this->periodTransition($id,$this->periodStatus((int)$p['status_id']),'CANCELLED','CANCEL');}
 private function periodTransition(int$id,string$from,string$to,string$action):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$c=$this->companyId($u);$p=$this->record('labour_wage_periods',$id,$c);if(!$p)return$this->notFound();$old=$this->periodStatus((int)$p['status_id']);if($old!==$from)return$this->response->setStatusCode(409)->setJSON(['success'=>false,'message'=>'Invalid wage-period status transition.']);$sid=$this->masterId('labour_wage_periods_status_masters','status_code',$to);$d=['status_id'=>$sid,'updated_by'=>(int)$u->id,'updated_at'=>$this->now()];if($to==='APPROVED')$d+=['approved_by'=>(int)$u->id,'approved_at'=>$this->now()];db_connect()->table('labour_wage_periods')->where('id',$id)->update($d);$this->statusLog($c,'WAGE_PERIOD',$id,$old,$to,$action,null,(int)$u->id);return$this->ok('Wage period '.strtolower($to).' successfully.','wage_period',$this->record('labour_wage_periods',$id,$c));}
 private function periodStatus(int$id):string{return(string)(db_connect()->table('labour_wage_periods_status_masters')->select('status_code')->where('id',$id)->get()->getRowArray()['status_code']??'UNKNOWN');}
 private function recalc(int$id):void{$r=db_connect()->table('labour_wage_lines')->select('COALESCE(SUM(regular_wage+overtime_wage),0) gross_wages,COALESCE(SUM(allowance_amount+incentive_amount),0) total_additions,COALESCE(SUM(advance_deduction+other_deduction),0) total_deductions,COALESCE(SUM(net_amount),0) net_payable',false)->where('wage_period_id',$id)->get()->getRowArray();db_connect()->table('labour_wage_periods')->where('id',$id)->update($r);}
}
